<template>
  <div class="dashboard">
    <header class="dashboardIntro">
      <div><span class="kicker">从一个故事，到一部短剧</span><h2>{{ project?.story.title || '开始你的下一部短剧' }}</h2><p>导入章节，集中查看剧本、资产、镜头与成片。</p></div>
      <div class="introActions"><button class="softButton" type="button" @click="emit('openStage', 'costs')"><icon-wallet :size="16" />{{ budgetLabel }}</button><button class="primaryButton autoButton" type="button" disabled aria-describedby="automationStatus"><icon-sparkles :size="18" />一键自动制作<span>待开放</span></button></div>
    </header>
    <section class="productionTrack" aria-label="制作流程">
      <div class="trackHeading"><strong><icon-route :size="18" />制作进度</strong><span id="automationStatus">可在分集工作台授权生成剧本，整片自动生产仍在接入。</span></div>
      <div class="workflow"><button v-for="(step, index) in workflow" :key="step.label" type="button" class="workflowStep" :class="{ ready: step.ready }" @click="emit('openStage', step.stage)"><span class="stepIndex"><icon-check v-if="step.ready" :size="16" /><template v-else>{{ String(index + 1).padStart(2, '0') }}</template></span><span class="stepText"><b>{{ step.label }}</b><small>{{ step.status }}</small></span><icon-chevron-right v-if="index < workflow.length - 1" class="stepArrow" :size="16" /></button></div>
    </section>
    <div v-if="attentionTasks || pendingReview" class="attentionBanner"><icon-info-circle :size="18" /><span>{{ attentionTasks ? `${attentionTasks} 个任务需要处理` : `${pendingReview} 个镜头待确认` }}</span><button type="button" @click="emit('openStage', attentionTasks ? 'tasks' : 'shots')">查看详情 →</button></div>
    <div class="creationGrid">
      <section class="studioPanel storyPanel">
        <div class="panelHeader"><div class="panelTitle"><span class="panelIcon"><icon-book-2 :size="20" /></span><div><h3>{{ project ? '故事与剧本' : '导入故事' }}</h3><small>{{ project ? '原文与改编，随时查看' : '支持小说章节原文' }}</small></div></div><button v-if="project" class="textButton" type="button" @click="emit('openStage', 'stories')">全部故事 {{ storyCount }} →</button></div>
        <template v-if="!project">
          <label for="studioNovelTitle">故事名称</label><input id="studioNovelTitle" v-model="novelTitle" maxlength="200" placeholder="给你的短剧起个名字" />
          <label for="studioNovelText">小说章节</label><textarea id="studioNovelText" v-model="novelText" maxlength="1000000" rows="7" placeholder="在这里粘贴章节原文…&#10;&#10;保留“第一章”等标题，便于软件识别章节。" />
          <div class="sourceActions"><input ref="novelFileInput" class="hiddenInput" type="file" accept=".txt,.md,.markdown,text/plain,text/markdown" @change="emit('fileChange', $event)" /><button class="softButton" type="button" @click="novelFileInput?.click()"><icon-upload :size="16" />导入文件</button><button class="primaryButton" type="button" :disabled="savingStory || !novelTitle.trim() || !novelText.trim()" @click="emit('importNovel')">{{ savingStory ? '保存中…' : '保存并识别章节' }}<icon-arrow-right :size="16" /></button></div>
        </template>
        <template v-else>
          <div class="storyTabs" aria-label="故事内容"><button type="button" :class="{ active: storyView === 'source' }" :aria-pressed="storyView === 'source'" @click="storyView = 'source'">章节原文 <span>{{ project.chapterIndex?.chapters.length ?? 0 }}</span></button><button type="button" :class="{ active: storyView === 'script' }" :aria-pressed="storyView === 'script'" @click="storyView = 'script'">分集剧本 <span>{{ project.episodes.length }}</span></button></div>
          <div class="scriptPaper">
            <template v-if="storyView === 'source'"><span class="paperLabel">已保存原文</span><h4>{{ project.story.title }}</h4><p class="sourceText">{{ project.story.sourceText.slice(0, 1800) }}{{ project.story.sourceText.length > 1800 ? '…' : '' }}</p></template>
            <template v-else-if="latestEpisode"><span class="paperLabel">第 {{ latestEpisode.episodeNumber }} 集</span><h4>{{ latestEpisode.title }}</h4><p>{{ latestEpisode.logline }}</p><ol><li v-for="(beat, index) in latestEpisode.outline" :key="index">{{ beat }}</li></ol><small>已保存 {{ latestEpisode.script.length }} 个剧本场次</small></template>
            <div v-else class="emptyContent"><icon-script :size="34" /><strong>还没有分集剧本</strong><span>前往分集工作台准备章节改编</span></div>
          </div>
          <p v-if="project.chapterIndex?.issues.length" class="sourceWarning">{{ project.chapterIndex.issues[0] }}</p>
          <div class="sourceActions"><span class="savedState"><icon-check :size="14" />原文已保存</span><button class="primaryButton" type="button" @click="emit('openStage', 'episodes')">进入分集工作台<icon-arrow-right :size="16" /></button></div>
        </template>
      </section>
      <section class="studioPanel previewPanel">
        <div class="panelHeader"><div class="panelTitle"><span class="panelIcon violetIcon"><icon-player-play :size="20" /></span><div><h3>成片预览</h3><small>每个故事，都值得被看见</small></div></div><span class="formatTag">竖屏短剧</span></div>
        <div class="previewStage"><div class="previewFrame"><span class="frameRatio">9:16</span><span class="playMark"><icon-player-play :size="25" /></span><strong>{{ synthesisCount ? '已有合成产物' : '等待第一部成片' }}</strong><small>{{ synthesisCount ? '前往成片管理查看任务记录' : '完成生成与合成后查看制作结果' }}</small></div><div class="previewCaption"><icon-movie :size="16" /><span>{{ synthesisCount ? `${synthesisCount} 个合成任务有产物` : '尚无可预览视频' }}</span></div></div>
        <div class="previewFooter"><div><strong>目标交付规格</strong><small>1080 × 1920 · MP4</small></div><button class="softButton" type="button" @click="emit('openStage', 'exports')">成片管理<icon-arrow-right :size="16" /></button></div>
      </section>
    </div>
    <section class="studioPanel assetsPanel">
      <div class="panelHeader"><div class="panelTitle"><span class="panelIcon mintIcon"><icon-box :size="20" /></span><div><h3>故事资产</h3><small>人物、场景和道具，集中管理与复用</small></div></div><button class="textButton" type="button" @click="emit('openStage', 'assets')">全部资产 →</button></div>
      <div class="assetTabs" aria-label="资产分类"><button v-for="tab in assetTabs" :key="tab.key" type="button" :class="{ active: assetView === tab.key }" :aria-pressed="assetView === tab.key" @click="assetView = tab.key"><component :is="tab.icon" :size="16" />{{ tab.label }}<span>{{ tab.count }}</span></button></div>
      <div v-if="visibleAssets.length" class="assetGrid"><article v-for="asset in visibleAssets" :key="asset.id" class="assetCard"><div class="assetVisual" :class="assetView"><component :is="assetView === 'scene' ? IconPhoto : assetView === 'prop' ? IconBox : IconUser" :size="27" /><span>待关联参考图</span></div><div class="assetInfo"><strong>{{ asset.name }}</strong><small :title="asset.description">{{ asset.description || '描述待补充' }}</small></div><span class="assetState" :class="{ locked: asset.locked }">{{ asset.locked ? '已锁定' : '待确认' }}</span></article></div>
      <div v-else class="assetEmpty"><span class="emptyAssetIcon"><component :is="assetView === 'scene' ? IconPhoto : assetView === 'prop' ? IconBox : IconUser" :size="26" /></span><div><strong>尚无{{ assetTabs.find(tab => tab.key === assetView)?.label }}资料</strong><p>已建立的资产会显示在这里，便于保持跨镜头一致性。</p></div></div>
    </section>
    <section class="studioPanel timelinePanel">
      <div class="panelHeader"><div class="panelTitle"><span class="panelIcon amberIcon"><icon-movie :size="20" /></span><div><h3>分镜时间轴</h3><small>{{ project?.shots.length ? `${project.shots.length} 个镜头 · 已规划 ${(totalDurationMs / 1000).toFixed(1)} 秒` : '按故事顺序查看镜头与生成状态' }}</small></div></div><button class="textButton" type="button" @click="emit('openStage', 'shots')">全部分镜 →</button></div>
      <div v-if="shots.length" class="shotStrip"><button v-for="shot in shots" :key="shot.id" type="button" class="shotCard" @click="emit('openStage', 'shots')"><div class="shotVisual"><span class="shotNumber">{{ shot.episodeNumber }}—{{ String(shot.sequence).padStart(2, '0') }}</span><icon-photo-video :size="28" /><span class="shotDuration">{{ (shot.durationMs / 1000).toFixed(1) }}s</span></div><strong>{{ shot.title || '未命名镜头' }}</strong><small :class="{ ready: shot.videoReadiness === 'ready' }">{{ shot.videoReadiness === 'ready' ? '视频就绪' : '待生成视频' }}</small></button></div>
      <div v-else class="timelineEmpty"><icon-photo-video :size="29" /><div><strong>分镜将在这里展开</strong><span>建立分镜后，可查看镜头顺序、时长与视频就绪状态。</span></div></div>
    </section>
  </div>
</template>

<script setup lang="ts">
import { computed, ref } from "vue";
import { IconArrowRight, IconBook2, IconBox, IconCheck, IconChevronRight, IconInfoCircle, IconMovie, IconPhoto, IconPhotoVideo, IconPlayerPlay, IconRoute, IconScript, IconSparkles, IconUpload, IconUser, IconWallet } from "@tabler/icons-vue";
import type { BudgetOverview, ProjectProduction } from "@/lib/productionApi";
type Stage = "stories" | "episodes" | "assets" | "shots" | "tasks" | "exports" | "costs";
const props = defineProps<{ project: ProjectProduction | null; storyCount: number; budget: BudgetOverview | null; savingStory: boolean }>();
const emit = defineEmits<{ openStage: [stage: Stage]; importNovel: []; fileChange: [event: Event] }>();
const novelTitle = defineModel<string>("storyTitle", { default: "" });
const novelText = defineModel<string>("storyText", { default: "" });
const novelFileInput = ref<HTMLInputElement>();
const storyView = ref<"source" | "script">("source");
const assetView = ref<"character" | "scene" | "prop">("character");
const latestEpisode = computed(() => props.project?.episodes[0] ?? null);
const shots = computed(() => props.project?.shots.slice(0, 12) ?? []);
const totalDurationMs = computed(() => props.project?.shots.reduce((total, shot) => total + shot.durationMs, 0) ?? 0);
const synthesisCount = computed(() => props.project?.tasks.filter(task => task.stage === "synthesis" && task.state === "succeeded" && task.outputCount > 0).length ?? 0);
const assetTabs = computed(() => [
  { key: "character" as const, label: "角色", icon: IconUser, count: props.project?.assets.filter(asset => asset.kind === "character").length ?? 0 },
  { key: "scene" as const, label: "场景", icon: IconPhoto, count: props.project?.scenes.length ?? 0 },
  { key: "prop" as const, label: "道具", icon: IconBox, count: props.project?.assets.filter(asset => asset.kind === "prop").length ?? 0 },
]);
const visibleAssets = computed(() => assetView.value === "scene"
  ? (props.project?.scenes ?? []).slice(0, 6).map(scene => ({ ...scene, description: scene.location || scene.atmosphere }))
  : (props.project?.assets ?? []).filter(asset => asset.kind === assetView.value).slice(0, 6).map(asset => ({ ...asset, description: asset.stableDescription })));
const budgetLabel = computed(() => !props.budget?.global.configured ? "设置预算"
  : props.budget.global.limitMicros <= 0 ? "付费已停止"
    : `预算占用 ${Math.round(props.budget.global.usedMicros / props.budget.global.limitMicros * 100)}%`);
const attentionTasks = computed(() => props.project?.tasks.filter(task => ["failed", "reconcile_required", "reconciling"].includes(task.state)).length ?? 0);
const pendingReview = computed(() => props.project?.shots.filter(shot => shot.reviewState !== "confirmed").length ?? 0);
const workflow = computed(() => [
  { label: "导入章节", stage: "stories" as Stage, ready: !!props.project, status: props.project ? "原文已保存" : "等待导入" },
  { label: "改编剧本", stage: "episodes" as Stage, ready: !!props.project?.episodes.length, status: props.project?.episodes.length ? `${props.project.episodes.length} 集资料` : "待建立" },
  { label: "建立资产", stage: "assets" as Stage, ready: !!(props.project?.assets.length || props.project?.scenes.length), status: `${(props.project?.assets.length ?? 0) + (props.project?.scenes.length ?? 0)} 项资料` },
  { label: "规划分镜", stage: "shots" as Stage, ready: !!props.project?.shots.length, status: `${props.project?.shots.length ?? 0} 个镜头` },
  { label: "生成片段", stage: "tasks" as Stage, ready: !!props.project?.shots.some(shot => shot.videoReadiness === "ready"), status: `${props.project?.shots.filter(shot => shot.videoReadiness === "ready").length ?? 0} 个视频就绪` },
  { label: "合成出片", stage: "exports" as Stage, ready: synthesisCount.value > 0, status: synthesisCount.value ? `${synthesisCount.value} 个任务有产物` : "待合成" },
]);
</script>

